// ── Extraer user_id, chat_id, mensaje y nombre del update de Telegram
const msg = $input.first().json.message;

if (!msg || !msg.text) {
  // Ignorar updates sin texto (fotos, stickers, etc.)
  return [];
}

const user_id = String(msg.from?.id || msg.chat?.id || '');
const chat_id = String(msg.chat?.id || user_id);
const mensaje = String(msg.text || '').trim();
const nombre  = String(msg.from?.first_name || msg.from?.username || user_id);

if (!user_id || !mensaje) {
  return [];
}

return [{ json: { user_id, chat_id, mensaje, nombre } }];

// ── Llamar a bot_core.py — toda la lógica está en Python
// Registra usuario, encola, llama Ollama, guarda historial
const { execSync } = require('child_process');

const input   = $input.first().json;
const user_id = input.user_id;
const chat_id = input.chat_id;
const nombre  = (input.nombre  || user_id).replace(/'/g, '');

// Escapar mensaje para argumento de línea de comandos
const mensaje = (input.mensaje || '').replace(/\\/g, '\\\\').replace(/'/g, "'\\'");

const PYTHON  = '/data/data/com.termux/files/usr/bin/python3';
const SCRIPT  = '/data/data/com.termux/files/home/bots/scripts/bot_core.py';

let stdout = '';
let stderr = '';

try {
  stdout = execSync(
    `${PYTHON} ${SCRIPT} enqueue` +
    ` --user_id '${user_id}'` +
    ` --chat_id '${chat_id}'` +
    ` --nombre  '${nombre}'` +
    ` --mensaje '${mensaje}'`,
    { timeout: 150000, encoding: 'utf8' }
  );
} catch (e) {
  stderr = e.message || String(e);
  stdout = e.stdout  || '';
}

return [{ json: {
  raw_stdout: stdout.trim(),
  raw_stderr: stderr.trim(),
  user_id,
  chat_id
}}];

// ── Parsear JSON retornado por bot_core.py
const input  = $input.first().json;
const stdout = input.raw_stdout || '{}';
const stderr = input.raw_stderr || '';

let data;
try {
  data = JSON.parse(stdout);
} catch(e) {
  data = { status: 'error', message: 'parse_failed: ' + stdout };
}

// Si hay error en Python, respuesta de fallback
if (data.status === 'error' || !data.respuesta) {
  data.respuesta = '⚠️ Error interno. Intenta de nuevo.';
  data._stderr   = stderr;
}

// Pasar chat_id desde nodo anterior si falta
if (!data.chat_id) {
  data.chat_id = input.chat_id;
}

return [{ json: data }];
